import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


class DecisionTree:
    """Simple regression decision tree."""
    def __init__(self, max_depth=5, min_samples_leaf=10):
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.tree = None

    def fit(self, X, y):
        self.tree = self._build(X, y, depth=0)

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < 2 * self.min_samples_leaf:
            return {'value': np.mean(y)}

        best_feat, best_thresh, best_score = None, None, float('inf')
        n = len(y)

        # Subsample features for speed
        n_features = X.shape[1]
        feat_indices = np.random.choice(n_features, min(n_features, 20), replace=False)

        for feat in feat_indices:
            vals = X[:, feat]
            # Try quantile-based thresholds
            thresholds = np.percentile(vals, np.linspace(10, 90, 9))
            for thresh in thresholds:
                left = vals <= thresh
                right = ~left
                if left.sum() < self.min_samples_leaf or right.sum() < self.min_samples_leaf:
                    continue
                score = (np.var(y[left]) * left.sum() + np.var(y[right]) * right.sum())
                if score < best_score:
                    best_score = score
                    best_feat = feat
                    best_thresh = thresh

        if best_feat is None:
            return {'value': np.mean(y)}

        left = X[:, best_feat] <= best_thresh
        return {
            'feat': best_feat,
            'thresh': best_thresh,
            'left': self._build(X[left], y[left], depth + 1),
            'right': self._build(X[~left], y[~left], depth + 1),
        }

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

    def _predict_one(self, x, node):
        if 'value' in node:
            return node['value']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Gradient boosted trees."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c.startswith('x')]

    X_train = train[feature_cols].values
    y_train = train[TARGET_COLUMN].values.astype(float)
    X_test = test[feature_cols].values

    np.random.seed(42)

    # Gradient boosting
    n_trees = 200
    learning_rate = 0.1
    max_depth = 5
    min_samples_leaf = 20

    preds_train = np.full(len(y_train), np.mean(y_train))
    preds_test = np.full(len(X_test), np.mean(y_train))

    for i in range(n_trees):
        residuals = y_train - preds_train
        tree = DecisionTree(max_depth=max_depth, min_samples_leaf=min_samples_leaf)
        tree.fit(X_train, residuals)
        preds_train += learning_rate * tree.predict(X_train)
        preds_test += learning_rate * tree.predict(X_test)

    predictions = pd.DataFrame({"prediction": preds_test})
    predictions.to_csv(output_csv, index=False)
